import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { TmdbError } from "@/lib/tmdb/client";
import { getMovieDetail } from "@/lib/tmdb/movies";
import { getTmdbBackdropUrl, getTmdbPosterUrl } from "@/lib/tmdb/image";
import { BookmarkButton } from "@/components/bookmark-button";
import ReviewForm from "@/components/movies/review-form";
import StatusMessage from "@/components/ui/status-message";

interface MovieDetailPageProps {
  params: Promise<{ movieId: string }>;
}

function parseMovieId(rawId: string) {
  const id = Number(rawId);
  return Number.isInteger(id) && id > 0 ? id : null;
}

// 같은 URL의 fetch는 한 번의 렌더 안에서 자동으로 합쳐져요(generateMetadata + 페이지).
async function loadMovie(rawId: string) {
  const movieId = parseMovieId(rawId);
  if (movieId === null) notFound();

  try {
    return await getMovieDetail(movieId);
  } catch (error) {
    if (error instanceof TmdbError && error.status === 404) notFound();
    throw error; // 그 외 오류는 error.tsx가 처리해요.
  }
}

export async function generateMetadata({ params }: MovieDetailPageProps): Promise<Metadata> {
  const { movieId } = await params;

  try {
    const movie = await loadMovie(movieId);
    const image = getTmdbBackdropUrl(movie.backdrop_path) ?? getTmdbPosterUrl(movie.poster_path);

    return {
      title: movie.title,
      description: movie.overview || movie.tagline,
      openGraph: {
        title: `${movie.title} | UMCine`,
        description: movie.overview || movie.tagline,
        images: image ? [image] : [],
      },
    };
  } catch {
    return { title: "영화 상세" };
  }
}

export default function MovieDetailPage({ params }: MovieDetailPageProps) {
  return (
    <Suspense
      fallback={
        <main className="mx-auto flex w-full max-w-6xl flex-1 items-start px-4 py-12 sm:px-6">
          <StatusMessage>영화 상세 정보를 불러오는 중이에요.</StatusMessage>
        </main>
      }
    >
      <MovieDetailScreen params={params} />
    </Suspense>
  );
}

async function MovieDetailScreen({ params }: MovieDetailPageProps) {
  const { movieId } = await params;
  const movie = await loadMovie(movieId);

  const posterUrl = getTmdbPosterUrl(movie.poster_path);
  const backdropUrl = getTmdbBackdropUrl(movie.backdrop_path);
  const genreNames = movie.genres.map((genre) => genre.name).join(", ");

  const runtime =
    typeof movie.runtime === "number"
      ? movie.runtime >= 60
        ? `${Math.floor(movie.runtime / 60)}시간 ${movie.runtime % 60}분`
        : `${movie.runtime}분`
      : "상영 시간 정보가 없어요.";

  return (
    <main className="flex-1 text-gray-900">
      <section className="relative isolate flex min-h-[270px] overflow-hidden bg-gray-950 text-white sm:min-h-[310px]">
        {backdropUrl ? (
          <Image
            src={backdropUrl}
            alt=""
            aria-hidden="true"
            fill
            sizes="100vw"
            loading="eager"
            className="-z-10 object-cover object-center"
          />
        ) : (
          <div className="absolute inset-0 -z-10 flex items-center justify-center bg-gray-500 text-sm text-white">
            이미지 없음
          </div>
        )}

        <div aria-hidden="true" className="absolute inset-0 -z-10 bg-gradient-to-r from-gray-950 via-gray-950/85 to-gray-950/35" />
        <div aria-hidden="true" className="absolute inset-0 -z-10 bg-gradient-to-t from-gray-950 via-transparent to-gray-950/20" />

        <div className="mx-auto flex w-full max-w-6xl flex-col justify-end px-4 py-6 sm:px-6 sm:py-8">
          <Link
            href="/"
            className="mb-auto inline-flex w-fit items-center gap-2 rounded-full px-1 py-1 text-xs font-medium text-white/90 transition hover:text-white"
          >
            <span aria-hidden="true">←</span> 영화 목록
          </Link>

          <div className="max-w-3xl pt-12 sm:pt-16">
            <h1 className="text-2xl font-extrabold leading-tight tracking-tight sm:text-4xl">{movie.title}</h1>
            <p className="mt-1 text-xs text-gray-200 sm:text-sm">{movie.original_title}</p>
            <p className="mt-2 text-[11px] font-medium text-gray-100 sm:text-xs">
              {movie.release_date} · {genreNames} · {runtime}
            </p>
          </div>
        </div>
      </section>

      <section className="min-h-[360px] bg-[#f5f6f8]">
        <div className="mx-auto grid max-w-6xl grid-cols-1 gap-7 px-4 py-6 sm:px-6 md:grid-cols-[140px_minmax(0,1fr)_260px] md:gap-6 lg:gap-8">
          <div className="relative mx-auto aspect-[2/3] w-36 self-start overflow-hidden rounded-lg bg-gray-200 shadow-xl md:mx-0 md:w-full">
            {posterUrl ? (
              <Image
                src={posterUrl}
                alt={`${movie.title} 포스터`}
                fill
                sizes="(min-width: 768px) 140px, 144px"
                className="object-cover"
              />
            ) : (
              <div className="flex h-full w-full items-center justify-center text-xs text-gray-600">이미지 없음</div>
            )}
          </div>

          <div className="min-w-0">
            <h2 className="text-base font-bold text-gray-900">{movie.tagline}</h2>
            <p className="mt-3 text-xs leading-6 text-gray-600 sm:text-sm">{movie.overview}</p>
            <BookmarkButton movieId={movie.id} variant="detail" showLabel />
          </div>

          <aside className="border-t border-gray-200 pt-5 md:border-l md:border-t-0 md:pl-6 md:pt-0">
            <h2 className="text-sm font-bold text-gray-900">내 평점</h2>
            <p className="mt-1 text-[10px] text-gray-400">별점을 주고, 후기는 선택이에요.</p>
            <ReviewForm />
          </aside>
        </div>
      </section>
    </main>
  );
}
